Description: This Terraform configuration creates an AWS Private NAT Gateway in a specified subnet. Because AWS Private NAT Gateways do not support Elastic IP allocation IDs, the configuration accepts an optional `elastic_ip_allocation_id` variable for documentation/input compatibility but does not attach it to the NAT Gateway. The NAT Gateway is tagged with `pike = "permissions"`.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region where resources will be created."
  type        = string
  default     = "us-east-1"
}

variable "existing_subnet_id" {
  description = "Optional existing subnet ID for the Private NAT Gateway. If empty, a new VPC and subnet are created."
  type        = string
  default     = ""
}

variable "elastic_ip_allocation_id" {
  description = "Optional Elastic IP allocation ID. Note: AWS Private NAT Gateways do not support Elastic IP allocation IDs, so this value is not attached."
  type        = string
  default     = ""
}

